def overlaps(a, b, c, d):
    """Return True if inclusive intervals [a, b] and [c, d] share any point."""
    return a <= d or c <= b

class RunningStats:
    """Accumulates numbers and reports their running sum and average.

    Each RunningStats instance is independent: numbers added to one
    instance must not affect the totals of any other instance.
    """

    samples = []

    def add(self, value):
        self.samples.append(value)

    def total(self):
        return sum(self.samples)

    def average(self):
        return sum(self.samples) / len(self.samples)
